// Relationship portraits [MM-story_mwpni0v4_3m] (was MM-task_mw9odkf0_4). The lists are generated by
// tools/dialog/expression_prompts.py from the files present. Every switched-on character has both extra portraits (the
// base is neutral). A file still byte-identical to its base is a placeholder and must be listed as one (so the game
// prints the status over it); any other must be an 864 × 1152 PNG.
import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { MOOD_PORTRAITS, PLACEHOLDER_PORTRAITS } from './portraitMoods.js';

const dir = new URL('../../content/dialog/portraits/', import.meta.url);
const pngSize = (buf) => (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) ? [buf.readUInt32BE(16), buf.readUInt32BE(20)] : null);

test('each switched-on character has antagonistic and friendly portraits: a flagged placeholder, or final 864 × 1152 PNG', () => {
  for (const slug of MOOD_PORTRAITS) {
    const base = readFileSync(new URL(`${slug}.png`, dir));
    let anyCopy = false;
    for (const mood of ['antagonistic', 'friendly']) {
      const url = new URL(`${slug}-${mood}.png`, dir);
      assert.ok(existsSync(url), `${slug}-${mood}.png is missing`);
      const buf = readFileSync(url);
      if (buf.equals(base)) { anyCopy = true; continue; }
      assert.deepEqual(pngSize(buf), [864, 1152], `${slug}-${mood}.png must be an 864 × 1152 PNG (or still the placeholder copy)`);
    }
    assert.equal(PLACEHOLDER_PORTRAITS.has(slug), anyCopy, `${slug}: the placeholder flag must match the files (re-run the tool)`);
  }
  for (const slug of PLACEHOLDER_PORTRAITS) assert.ok(MOOD_PORTRAITS.has(slug), `${slug} is a placeholder but not switched on`);
});
